#include <iostream>
#include <iomanip>
#include <string>
#include <stdexcept>

class StandaloneBasePlusCommissionEmployee {
private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales{0.0};
    double commissionRate{0.0};
    double baseSalary{0.0};

public:
    StandaloneBasePlusCommissionEmployee(
        std::string first, std::string last, std::string ssn,
        double sales = 0.0, double rate = 0.0, double salary = 0.0)
        : firstName(std::move(first)), lastName(std::move(last)),
          socialSecurityNumber(std::move(ssn))
    {
        setGrossSales(sales);
        setCommissionRate(rate);
        setBaseSalary(salary);
    }

    void setGrossSales(double sales) {
        if (sales >= 0.0) { grossSales = sales; }
        else { throw std::invalid_argument("Gross sales must be >= 0.0"); }
    }
    double getGrossSales() const { return grossSales; }

    void setCommissionRate(double rate) {
        if (rate > 0.0 && rate < 1.0) { commissionRate = rate; }
        else { throw std::invalid_argument("Commission rate must be > 0.0 and < 1.0"); }
    }
    double getCommissionRate() const { return commissionRate; }

    void setBaseSalary(double salary) {
        if (salary >= 0.0) { baseSalary = salary; }
        else { throw std::invalid_argument("Salary must be >= 0.0"); }
    }
    double getBaseSalary() const { return baseSalary; }

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }

    double earnings() const {
        return baseSalary + (commissionRate * grossSales);
    }

    void print() const {
        std::cout << "base-salaried commission employee: " << firstName << ' ' << lastName
                  << "\nsocial security number: " << socialSecurityNumber
                  << "\ngross sales: " << grossSales
                  << "\ncommission rate: " << commissionRate
                  << "\nbase salary: " << baseSalary;
    }
};

int main() {
    StandaloneBasePlusCommissionEmployee employee("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Employee information obtained by get functions:\n"
              << "\nFirst name is " << employee.getFirstName()
              << "\nLast name is " << employee.getLastName()
              << "\nSocial security number is " << employee.getSocialSecurityNumber()
              << "\nGross sales is " << employee.getGrossSales()
              << "\nCommission rate is " << employee.getCommissionRate()
              << "\nBase salary is " << employee.getBaseSalary() << std::endl;

    employee.setBaseSalary(1000.0);
    std::cout << "\nUpdated employee information output by print function:\n" << std::endl;
    employee.print();
    std::cout << "\n\nEmployee's earnings: $" << employee.earnings() << std::endl;

    return 0;
}

body.vi:
Để định nghĩa một lớp dẫn xuất (derived class) từ một lớp cơ sở (base class), C++ sử dụng dấu hai chấm (`:`) sau tên lớp dẫn xuất, theo sau là từ khóa phạm vi truy cập (như `public`) và tên lớp cơ sở:
```cpp
class BasePlusCommissionEmployee : public CommissionEmployee {
    // ...
};
```
Từ khóa `public` thiết lập kiểu kế thừa công khai. Theo đó, đối tượng của lớp dẫn xuất `BasePlusCommissionEmployee` mang quan hệ 'is-a' (là một) `CommissionEmployee`. Lớp dẫn xuất thừa hưởng tất cả các thành viên của lớp cơ sở và có thể bổ sung các thành viên dữ liệu hoặc hàm nghiệp vụ chuyên biệt của riêng mình (chẳng hạn như `baseSalary`, `setBaseSalary()`, `getBaseSalary()`).

body.en:
To define a derived class inheriting from a base class, C++ uses a colon (`:`) followed by an access specifier (such as `public`) and the base class name:
```cpp
class BasePlusCommissionEmployee : public CommissionEmployee {
    // ...
};
```
The `public` keyword denotes public inheritance, asserting an 'is-a' relationship: a `BasePlusCommissionEmployee` is a `CommissionEmployee`. The derived class inherits members of the base class and extends them with specialized data members and behaviors (e.g., `baseSalary`, `setBaseSalary()`, `getBaseSalary()`).

