#include <iostream>
#include <iomanip>
#include <string>
#include <utility>

// Base class representing a commission-only employee
class CommissionEmployee {
private:
    std::string firstName;
    std::string lastName;
    std::string socialSecurityNumber;
    double grossSales{0.0};
    double commissionRate{0.0};

public:
    CommissionEmployee(std::string first, std::string last, std::string ssn,
                       double sales = 0.0, double rate = 0.0)
        : firstName(std::move(first)), lastName(std::move(last)),
          socialSecurityNumber(std::move(ssn)), grossSales(sales), commissionRate(rate) {}

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }
    std::string getSocialSecurityNumber() const { return socialSecurityNumber; }
    double getGrossSales() const { return grossSales; }
    double getCommissionRate() const { return commissionRate; }

    double earnings() const {
        return commissionRate * grossSales;
    }
};

// Derived class inheriting from CommissionEmployee
class BasePlusCommissionEmployee : public CommissionEmployee {
private:
    double baseSalary{0.0};

public:
    BasePlusCommissionEmployee(std::string first, std::string last, std::string ssn,
                               double sales, double rate, double salary)
        : CommissionEmployee(std::move(first), std::move(last), std::move(ssn), sales, rate),
          baseSalary(salary) {}

    void setBaseSalary(double salary) { baseSalary = salary; }
    double getBaseSalary() const { return baseSalary; }

    // Specialized earnings adding base salary to commission
    double earnings() const {
        return baseSalary + CommissionEmployee::earnings();
    }
};

int main() {
    BasePlusCommissionEmployee emp("Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0);

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Derived employee using inherited getters:\n";
    std::cout << "Name: " << emp.getFirstName() << " " << emp.getLastName() << "\n";
    std::cout << "SSN: " << emp.getSocialSecurityNumber() << "\n";
    std::cout << "Base Salary: $" << emp.getBaseSalary() << "\n";
    std::cout << "Initial Earnings: $" << emp.earnings() << "\n";

    emp.setBaseSalary(1000.0);
    std::cout << "\nAfter updating base salary:\n";
    std::cout << "Base Salary: $" << emp.getBaseSalary() << "\n";
    std::cout << "Updated Earnings: $" << emp.earnings() << std::endl;

    return 0;
}
